    void AddBranding(RtsUI ui){ui.AddTitle("Reusable identity, colours and typography.","Branding Presets");foreach(var p in Presets("branding"))AddBrandingPreset(ui,p as JObject);ui.AddClickableButton("Add Branding Preset","Create a new reusable Branding Preset.","Add Branding Preset","blue","Branding Presets",()=>{AddPreset("branding");ui.RebuildUI(Build);});}
    void AddBrandingPreset(RtsUI ui,JObject p){var id=(string)p?["id"];if(string.IsNullOrWhiteSpace(id))return;ui.BeginSection((string)p["name"]??id,"Branding Presets");ui.AddTextbox("Preset Name","Display name for this Branding Preset.","Branding Presets",K("branding",id,"name"),(string)p["name"]??"Branding",false);Dropdown(ui,"Source Platform","Optional platform this Branding Preset matches for automatic source branding.","Branding Presets",K("branding",id,"platform"),new[]{"","Twitch","Kick","YouTube"},(string)p["platform"]??"");ui.BeginRow();Colour(ui,"Primary Colour","primaryColor",p,"#0384CBFF");Colour(ui,"Secondary Colour","secondaryColor",p,"#101416FF");ui.EndRow();ui.BeginRow();Colour(ui,"Title Colour","titleColor",p,"#FFFFFFFF");Colour(ui,"Title Prefix / Suffix Colour","titlePrefixSuffixColor",p,"#0384CBFF");ui.EndRow();ui.BeginRow();Colour(ui,"Text Colour","textColor",p,"#FFFFFFFF");Colour(ui,"Shadow Colour","shadowColor",p,"#000000FF");ui.EndRow();ui.BeginRow();ui.AddGoogleFontSelector("Font","Google Font used by branded text.","Branding Presets",K("branding",id,"font"),(string)p["font"]??"Inter");ui.AddNumericTextbox("Font Size","Default branded font size in pixels.","Branding Presets",K("branding",id,"fontSize"),(int?)p["fontSize"]??34,12,96);ui.EndRow();ui.AddTextbox("Logo URL","HTTPS URL of the branding logo.","Branding Presets",K("branding",id,"logo"),(string)p["logo"]??"",false);ui.BeginRow();ui.AddTextbox("Fallback Text","Text used when no logo is defined.","Branding Presets",K("branding",id,"fallbackText"),(string)p["fallbackText"]??"RTS",false);ui.AddTextbox("Brand Label","Label displayed beside the logo or fallback text.","Branding Presets",K("branding",id,"brandLabel"),(string)p["brandLabel"]??"ACTION REPLAY",false);ui.EndRow();if(!IsBuiltInBranding(id))ui.AddClickableButton("Remove Preset","Delete this Branding Preset.","Remove Preset","red","Branding Presets",()=>{RemovePreset("branding",id);ui.RebuildUI(Build);});ui.EndSection();}
