    void AddDesigns(RtsUI ui){ui.AddTitle("Design Presets define the visual treatment: Broadcast, Cut, Cinematic and Minimal.","Design Presets");foreach(var id in new[]{"broadcast","cut","cinematic","minimal"}){var p=Find("visual",id);if(p!=null)AddDesign(ui,p);}}
    void AddDesign(RtsUI ui,JObject p){var id=(string)p?["id"];if(string.IsNullOrWhiteSpace(id))return;var name=(string)p["name"]??id;if(id=="broadcast"){ui.BeginSection(name,"Design Presets");Broadcast(ui,p);ui.EndSection();}else if(id=="cut"){ui.BeginSection(name,"Design Presets");Cut(ui,p);ui.EndSection();}else ui.AddTitle(name,"Design Presets");}
