    void AddTitles(RtsUI ui){ui.AddTitle("Title Presets define reusable Title Behaviour.","Title Presets");foreach(var p in Presets("title"))AddTitle(ui,p as JObject);ui.AddClickableButton("Add Title Preset","Create a new reusable Title Behaviour preset.","Add Title Preset","blue","Title Presets",()=>{AddPreset("title");ui.RebuildUI(Build);});}
    void AddTitle(RtsUI ui,JObject p){var id=(string)p?["id"];if(string.IsNullOrWhiteSpace(id))return;ui.BeginSection((string)p["name"]??id,"Title Presets");ui.AddTextbox("Preset Name","Display name for this Title Preset.","Title Presets",K("title",id,"name"),(string)p["name"]??"Title Behaviour",false);ui.BeginRow();Dropdown(ui,"Decoration Position","Position of the title prefix or suffix decoration.","Title Presets",K("title",id,"decorationPosition"),new[]{"Prefix","Suffix"},(string)p["decorationPosition"]??"Prefix");Dropdown(ui,"Title Position","Place the replay title at the top or bottom of the video.","Title Presets",K("title",id,"position"),new[]{"Top","Bottom"},(string)p["position"]??"Bottom");ui.EndRow();ui.AddTextbox("Decoration","Text added before or after the replay title.","Title Presets",K("title",id,"decoration"),(string)p["decoration"]??"Action Replay -",false);ui.BeginRow();Dropdown(ui,"Animation","Animation used when the title enters and leaves the player.","Title Presets",K("title",id,"animation"),new[]{"Left to right","Right to left","Slide up/down"},(string)p["animation"]??"Left to right");TitleInt(ui,"Show Delay","delay",p,2000,0,60000);TitleInt(ui,"Display Duration","duration",p,10000,0,120000);TitleInt(ui,"Animation Duration","animationDuration",p,1000,0,10000);ui.EndRow();if(id!="default")ui.AddClickableButton("Remove Preset","Delete this Title Preset.","Remove Preset","red","Title Presets",()=>{RemovePreset("title",id);ui.RebuildUI(Build);});ui.EndSection();}
    void AddEntries(RtsUI ui,string key,string category,string[] ids,string[] labels){var c=Read(key);var es=c["entryPoints"] as JObject??new JObject();ui.AddTitle("Each entry point selects an Animation Profile, Design Preset, Title Preset and Branding Preset.",category);if(key==PlayerKey)ui.AddToggleSwitch("Use Source Platform Branding","If enabled, use a Branding Preset assigned to the replay's source platform. If none exists, the Play — Replay Branding Preset is used.",category,EK(key,"play","useSourcePlatformBranding"),(bool?)es["play"]?["useSourcePlatformBranding"]??false);for(var i=0;i<ids.Length;i++){var id=ids[i];var e=es[id] as JObject??new JObject();ui.BeginSection(labels[i],category);ui.BeginRow();Dropdown(ui,"Branding Preset","Branding preset used by this entry point.",category,EK(key,id,"brandingPreset"),Names("branding"),Name("branding",(string)e["brandingPreset"]??"default"));Dropdown(ui,"Design Preset","Visual design used by this entry point.",category,EK(key,id,"designPreset"),Names("visual"),Name("visual",(string)e["designPreset"]??(string)e["visualPreset"]??"broadcast"));ui.EndRow();ui.BeginRow();Dropdown(ui,"Title Preset","Title Behaviour used by this entry point.",category,EK(key,id,"titlePreset"),Names("title"),Name("title",(string)e["titlePreset"]??"default"));Dropdown(ui,"Animation Profile","Animation profile used by this entry point.",category,EK(key,id,"animationProfile"),AnimationNames(key),AnimationName(key,(string)e["animationProfile"]??"default"));ui.EndRow();ui.EndSection();}}
    void AddClapper(RtsUI ui){var c=Read(ClapperKey);var e=c["entryPoint"] as JObject??new JObject();ui.AddTitle("Clapperboard uses an Animation Profile and Branding Preset.","Clapperboard");Dropdown(ui,"Animation Profile","Animation profile used by the Clapperboard.","Clapperboard",UiPrefix+"clapper.animation",AnimationNames(ClapperKey),AnimationName(ClapperKey,(string)e["animationProfile"]??"default"));Dropdown(ui,"Branding Preset","Branding preset used by the Clapperboard.","Clapperboard",UiPrefix+"clapper.branding",Names("branding"),Name("branding",(string)e["brandingPreset"]??"default"));}
    void Colour(RtsUI ui,string l,string f,JObject p,string d)=>ui.AddColorPicker(l,"Branding colour.","Branding Presets",K("branding",(string)p["id"],f),(string)p[f]??d);
    void DesignInt(RtsUI ui,string l,string f,JObject p,int d,int min,int max)=>ui.AddNumericTextbox(l,"Design preset setting.","Design Presets",K("visual",(string)p["id"],f),(int?)p[f]??d,min,max);
