    string K(string t,string id,string f)=>UiPrefix+t+"."+id+"."+f;string EK(string c,string id,string f)=>UiPrefix+"entry."+c+"."+id+"."+f;
    JArray Presets(string t)=>Read(PresetsKey)[t] as JArray??new JArray();JObject Find(string t,string id){foreach(var p in Presets(t))if(string.Equals((string)p["id"],id,StringComparison.OrdinalIgnoreCase))return p as JObject;return null;}
    string[] Names(string t){var a=new List<string>();foreach(var p in Presets(t)){var n=(string)p["name"];if(!string.IsNullOrWhiteSpace(n))a.Add(n);}return a.Count>0?a.ToArray():new[]{t=="visual"?"Broadcast":"Default"};}
    string Name(string t,string id){var p=Find(t,id);return p==null?(t=="visual"?"Broadcast":"Default"):(string)p["name"]??id;}
    JArray Animations(string k)=>Read(k)["animationProfiles"] as JArray??new JArray();string[] AnimationNames(string k){var a=new List<string>();foreach(var p in Animations(k)){var n=(string)p["name"];if(!string.IsNullOrWhiteSpace(n))a.Add(n);}return a.Count>0?a.ToArray():new[]{"Default"};}
    string AnimationName(string k,string id){foreach(var p in Animations(k))if(string.Equals((string)p["id"],id,StringComparison.OrdinalIgnoreCase))return(string)p["name"]??id;return id=="default"?"Default":id;}
    string ReadUi(string key){if(!key.StartsWith(UiPrefix,StringComparison.Ordinal))return CPH.GetGlobalVar<string>(key,true);var p=key.Substring(UiPrefix.Length).Split('.');try{if(p[0]=="branding"||p[0]=="visual"||p[0]=="title")return Find(p[0],p[1])?[p[2]]?.ToString()??"";if(p[0]=="entry")return EntryValue(p[1],p[2],p[3]);if(p[0]=="clapper")return p[1]=="animation"?AnimationName(ClapperKey,(string)Read(ClapperKey)["entryPoint"]?["animationProfile"]??"default"):Name("branding",(string)Read(ClapperKey)["entryPoint"]?["brandingPreset"]??"default");}catch{}return "";}
    string EntryValue(string c,string id,string field){var e=(Read(c)["entryPoints"] as JObject)?[id] as JObject??new JObject();if(field=="animationProfile")return AnimationName(c,(string)e[field]??"default");if(field=="useSourcePlatformBranding")return ((bool?)e[field]??false).ToString();return field=="designPreset"?Name("visual",(string)e["designPreset"]??(string)e["visualPreset"]??"broadcast"):field=="titlePreset"?Name("title",(string)e["titlePreset"]??"default"):Name("branding",(string)e["brandingPreset"]??"default");}
    void SaveUi(string key,object value,bool persisted){if(!key.StartsWith(UiPrefix,StringComparison.Ordinal)){CPH.SetGlobalVar(key,value,persisted);return;}var p=key.Substring(UiPrefix.Length).Split('.');var v=value?.ToString()??"";try{if(p[0]=="branding"||p[0]=="visual"||p[0]=="title")SavePreset(p[0],p[1],p[2],v);else if(p[0]=="entry")SaveEntry(p[1],p[2],p[3],v);else if(p[0]=="clapper")SaveClapper(p[1],v);}catch(Exception ex){CPH.LogWarn("RTS Action Replay preset settings save failed: "+ex.Message);}}
    void SavePreset(string t,string id,string f,string v){var config=Read(PresetsKey);var presets=config[t] as JArray??new JArray();JObject preset=null;foreach(var item in presets){if(string.Equals((string)item["id"],id,StringComparison.OrdinalIgnoreCase)){preset=item as JObject;break;}}if(preset==null){CPH.LogWarn("RTS Action Replay preset settings: preset not found for save: "+t+"/"+id);return;}preset[f]=Parse(v);Save(PresetsKey,config);}
    void SaveEntry(string c,string id,string f,string v){var x=Read(c);var es=x["entryPoints"] as JObject??new JObject();var e=es[id] as JObject??new JObject();if(f=="animationProfile")e[f]=ResolveAnimation(c,v);else if(f=="designPreset")e["designPreset"]=ResolveId("visual",v);else if(f=="titlePreset")e["titlePreset"]=ResolveId("title",v);else if(f=="useSourcePlatformBranding")e[f]=bool.TryParse(v,out var enabled)&&enabled;else e["brandingPreset"]=ResolveId("branding",v);es[id]=e;x["entryPoints"]=es;Save(c,x);}
    void SaveClapper(string f,string v){var x=Read(ClapperKey);var e=x["entryPoint"] as JObject??new JObject();if(f=="animation")e["animationProfile"]=ResolveAnimation(ClapperKey,v);else e["brandingPreset"]=ResolveId("branding",v);x["entryPoint"]=e;Save(ClapperKey,x);}
    string ResolveAnimation(string k,string n){foreach(var p in Animations(k))if(string.Equals((string)p["name"],n,StringComparison.OrdinalIgnoreCase))return(string)p["id"]??"default";return"default";}string ResolveId(string t,string n){foreach(var p in Presets(t))if(string.Equals((string)p["name"],n,StringComparison.OrdinalIgnoreCase))return(string)p["id"]??"default";return"default";}
    JToken Parse(string v){if(int.TryParse(v,out var i))return i;if(bool.TryParse(v,out var b))return b;return v;}JObject Read(string k,JObject f){var s=CPH.GetGlobalVar<string>(k,true);try{return string.IsNullOrWhiteSpace(s)?f:JObject.Parse(s);}catch{return f;}}void Save(string k,JObject v)=>CPH.SetGlobalVar(k,v.ToString(Newtonsoft.Json.Formatting.None),true);void AddPreset(string t){var config=Read(PresetsKey);var a=config[t] as JArray??new JArray();var source=FindInArray(a,"default");var n="New "+(t=="visual"?"Design":"Preset");var id=Guid.NewGuid().ToString("N");JObject preset;if(source!=null){preset=(JObject)source.DeepClone();preset["id"]=id;preset["name"]=n;}else{preset=new JObject{{"id",id},{"name",n}};}a.Add(preset);config[t]=a;Save(PresetsKey,config);}JObject FindInArray(JArray a,string id){foreach(var p in a??new JArray())if(string.Equals((string)p["id"],id,StringComparison.OrdinalIgnoreCase))return p as JObject;return null;}void RemovePreset(string t,string id){var config=Read(PresetsKey);var a=config[t] as JArray??new JArray();JObject p=null;foreach(var item in a){if(string.Equals((string)item["id"],id,StringComparison.OrdinalIgnoreCase)){p=item as JObject;break;}}if(p!=null)a.Remove(p);config[t]=a;Save(PresetsKey,config);}
